function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure in the center
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // crowd around the center figure
  for (let i = 0; i < 10; i++) {
    let x = W/2 + Math.cos(t + i) * 100;
    let y = H/2 + Math.sin(t + i) * 100;
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 10);
    ctx.lineTo(x, y + 20);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 15);
    ctx.lineTo(x - 10, y + 20);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 15);
    ctx.lineTo(x + 10, y + 20);
    ctx.stroke();
  }

  ctx.restore();
}
